package main
import("encoding/json";"fmt";"io";"os";"path/filepath";"strconv";"strings";"sync";"time")
var logMu sync.Mutex
func logger(s string){logMu.Lock();defer logMu.Unlock();dir:=dataRoot();if os.MkdirAll(dir,0700)!=nil{return};p:=filepath.Join(dir,"plugin.log");if st,e:=os.Stat(p);e==nil&&st.Size()>128*1024{_=os.Remove(p+".previous");_=os.Rename(p,p+".previous")};f,e:=os.OpenFile(p,os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);if e==nil{defer f.Close();if len(s)>1000{s=s[:1000]};fmt.Fprintf(f,"%s %s\r\n",time.Now().Format(time.RFC3339),s)}}
func parseArgs(argv []string)(map[string]string,error){m:=map[string]string{};for i:=0;i<len(argv);i++{key:=strings.TrimLeft(argv[i],"-");if p:=strings.SplitN(key,"=",2);len(p)==2{m[p[0]]=p[1];continue};if i+1>=len(argv){return nil,fmt.Errorf("Missing SDK argument value.")};i++;m[key]=argv[i]};return m,nil}
func packageRoot()(string,error){e,err:=os.Executable();return filepath.Dir(filepath.Dir(e)),err}
func diagnostic(){p:=filepath.Join(dataRoot(),"status.json");b,e:=os.ReadFile(p);if e!=nil{b=[]byte("No runtime status yet. Add Info board > FoughtApple > NickNacks Orders.\r\n")};c,e:=readConfig(filepath.Join(dataRoot(),"settings.json"));if e!=nil{c=defaults()};meta,_:=json.MarshalIndent(c.public(),"","  ");report:=[]byte("NICKNACKS ORDERS DIAGNOSTIC - NO TOKEN VALUES\r\nContains endpoint/store URLs and aggregate counts only.\r\n\r\n");report=append(report,b...);report=append(report,[]byte("\r\n\r\nSaved configuration (public fields):\r\n")...);report=append(report,meta...);_=os.MkdirAll(dataRoot(),0700);p=filepath.Join(dataRoot(),"diagnostic.txt");if os.WriteFile(p,report,0600)==nil{_=openReport(p)}}
func main(){root,e:=packageRoot();if e!=nil{return};if len(os.Args)==2&&os.Args[1]=="--validate"{a,e:=loadArt(root);if e==nil{_,e=a.render(nil)};if e!=nil{os.Exit(2)};return};if len(os.Args)==2&&os.Args[1]=="--diagnose"{diagnostic();return};if len(os.Args)==3&&os.Args[1]=="--render-examples"{root=os.Args[2];a,e:=loadArt(root);if e!=nil{panic(e)};for _,s:=range []string{"?","0","7","12","137","1248"}{var n *int64;if s!="?"{v,_:=strconv.ParseInt(s,10,64);n=&v};b,e:=a.render(n);if e!=nil{panic(e)};name:=s;if s=="?"{name="unknown"};_=os.WriteFile(filepath.Join(root,"images","example-"+name+".svg"),b,0600)};return};if len(os.Args)==1{notify("Install this as a Stream Dock plugin. Use Info board > FoughtApple > NickNacks Orders, not Toolbox > Open.");return};args,e:=parseArgs(os.Args[1:]);if e!=nil{return};port,e:=strconv.Atoi(args["port"]);if e!=nil||port<1||port>65535||args["pluginUUID"]==""{logger("Missing Stream Dock SDK arguments.");return};release,ok:=acquireInstance();if !ok{return};defer release();e=runPlugin(port,args["pluginUUID"],args["registerEvent"],root,filepath.Join(dataRoot(),"settings.json"));if e!=nil&&e!=io.EOF{logger("Stream Dock connection closed.")}}
